52	export function Waitlist() {
53	  const rootRef = useRef<HTMLDivElement | null>(null);
54	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
55	  const [mode, setMode] = useState<Mode>(initialMode);
56	  const [email, setEmail] = useState("");
57	  const [status, setStatus] = useState<Status>("idle");
58	  const [error, setError] = useState<string | null>(null);
59	  const join = useMutation(api.waitlist.joinWaitlist);
