169	// A layered parallax field drifting rightward -- deeper (bigger, brighter)
170	// stars move faster. Returns its own teardown. Ported from the approved
171	// prototype so the shipped page matches it exactly.
172	function startDrift(canvas: HTMLCanvasElement): () => void {
173	  const ctx = canvas.getContext("2d");
174	  if (ctx === null) return () => {};
175	  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
176	  let w = 0;
177	  let h = 0;
178	  let raf = 0;
179	  let stars: Star[] = [];
180	
181	  function size() {
182	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
183	    w = canvas.clientWidth;
184	    h = canvas.clientHeight;
185	    canvas.width = w * dpr;
186	    canvas.height = h * dpr;
187	    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
188	  }
189	
190	  function build() {
191	    size();
192	    const count = Math.min(300, Math.floor((w * h) / 3600));
193	    stars = [];
194	    for (let i = 0; i < count; i++) {
195	      const depth = Math.random();
196	      stars.push({
197	        x: Math.random() * w,
198	        y: Math.random() * h,
199	        size: 0.5 + depth * 1.6,
200	        base: 0.1 + depth * 0.45,
201	        sp: 0.05 + depth * 0.22,
202	        tw: Math.random() * 6.28,
203	        hot: Math.random() < 0.04,
204	      });
205	    }
206	  }
207	
208	  function frame(t: number) {
209	    const time = t / 1000;
210	    ctx!.clearRect(0, 0, w, h);
211	    for (const s of stars) {
212	      if (!reduce) {
213	        s.x += s.sp;
214	        if (s.x > w + 2) s.x = -2;
215	      }
216	      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
217	      ctx!.beginPath();
218	      ctx!.arc(s.x, s.y, s.size, 0, 6.2832);
219	      if (s.hot) {
220	        ctx!.fillStyle = `rgba(10,132,255,${s.base + 0.2})`;
221	        ctx!.shadowColor = "rgba(10,132,255,.8)";
222	        ctx!.shadowBlur = 6;
223	      } else {
224	        ctx!.fillStyle = `rgba(255,255,255,${s.base * tw})`;
225	        ctx!.shadowBlur = 0;
226	      }
227	      ctx!.fill();
228	    }
229	    ctx!.shadowBlur = 0;
230	    if (!reduce) raf = requestAnimationFrame(frame);
231	  }
232	
233	  function onResize() {
234	    build();
235	    if (reduce) frame(0);
236	  }
237	
238	  build();
239	  if (reduce) frame(0);
240	  else raf = requestAnimationFrame(frame);
241	  window.addEventListener("resize", onResize);
242	
243	  return () => {
244	    cancelAnimationFrame(raf);
245	    window.removeEventListener("resize", onResize);
246	  };
247	}
