79	async function callOpenAI(path: string, body: unknown): Promise<unknown> {
80	  const response = await fetch(`${baseUrl}/v1/${path}`, {
81	    method: "POST",
82	    headers: {
83	      "Content-Type": "application/json",
84	      Authorization: `Bearer ${apiKey()}`,
85	    },
86	    body: JSON.stringify(body),
87	  });
88	  if (!response.ok) {
89	    const detail = await response.text();
90	    throw new Error(`OpenAI ${path} failed (${response.status}): ${detail}`);
91	  }
92	  return await response.json();
93	}
