151	export async function embedText(text: string): Promise<number[]> {
152	  const result = (await callOpenAI("embeddings", {
153	    model: "text-embedding-3-small",
154	    input: text,
155	  })) as { data?: Array<{ embedding?: number[] }> };
156	
157	  const embedding = result.data?.[0]?.embedding;
158	  if (embedding === undefined) {
159	    throw new Error("OpenAI returned no embedding");
160	  }
161	  return embedding;
162	}
