// The confirmation email greets people by the name they type, so we keep it
// tidy but permissive: trim and collapse inner whitespace runs, nothing more.
// Real names carry accents, hyphens, and apostrophes -- we do not police those.
export const MAX_WAITLIST_NAME_LENGTH = 80;

export function normalizeWaitlistName(raw: string): string {
  return raw.trim().replace(/\s+/g, " ");
}

// A usable name is non-empty after normalizing and within a sane ceiling, so a
// pasted essay can never land in the greeting or the stored row.
export function isValidWaitlistName(raw: string): boolean {
  const name = normalizeWaitlistName(raw);
  return name.length >= 1 && name.length <= MAX_WAITLIST_NAME_LENGTH;
}

