/// <reference types="vite/client" />
import { convexTest } from "convex-test";
import { expect, test, vi } from "vitest";
import { api } from "./_generated/api";
import schema from "./schema";
import { MAX_JOINS_PER_MINUTE } from "./waitlist";

const modules = import.meta.glob("./**/*.ts");

test("joinWaitlist stores a normalized email and name and reports joined", async () => {
  const t = convexTest(schema, modules);

  const result = await t.mutation(api.waitlist.joinWaitlist, {
    email: "  Tony@Example.COM ",
    name: "  Tony   Nguyen  ",
    source: "desktop",
  });
  expect(result).toEqual({ status: "joined" });

  const rows = await t.run((ctx) => ctx.db.query("waitlist").collect());
  expect(rows).toHaveLength(1);
  expect(rows[0].email).toBe("tony@example.com");
  // Name is trimmed and inner whitespace collapsed, not lowercased.
  expect(rows[0].name).toBe("Tony Nguyen");
  expect(rows[0].source).toBe("desktop");
});

test("a new join schedules exactly one confirmation email", async () => {
  const t = convexTest(schema, modules);

  await t.mutation(api.waitlist.joinWaitlist, {
    email: "a@b.com",
    name: "Ada",
    source: "desktop",
  });

  const scheduled = await t.run((ctx) =>
    ctx.db.system.query("_scheduled_functions").collect(),
  );
  expect(scheduled).toHaveLength(1);
  expect(scheduled[0].name).toBe("waitlist.js:sendConfirmationEmail");

  // With no RESEND_API_KEY set the action must run to completion as a no-op,
  // never throwing -- a missing provider can't break the join flow.
  await expect(
    t.finishAllScheduledFunctions(vi.runAllTimers),
  ).resolves.not.toThrow();
});

test("joining the same address again is idempotent and does not re-email", async () => {
  const t = convexTest(schema, modules);

  await t.mutation(api.waitlist.joinWaitlist, {
    email: "a@b.com",
    name: "Ada",
    source: "phone",
  });
  const again = await t.mutation(api.waitlist.joinWaitlist, {
    email: "A@B.com",
    name: "Someone Else",
    source: "desktop",
  });

  expect(again).toEqual({ status: "already" });
  const rows = await t.run((ctx) => ctx.db.query("waitlist").collect());
  expect(rows).toHaveLength(1);
  // A re-join must not overwrite the source or name captured the first time.
  expect(rows[0].source).toBe("phone");
  expect(rows[0].name).toBe("Ada");

  // Only the first join scheduled a confirmation; the "already" path emails no one.
  const scheduled = await t.run((ctx) =>
    ctx.db.system.query("_scheduled_functions").collect(),
  );
  expect(scheduled).toHaveLength(1);
});

test("an invalid email is rejected and stores nothing", async () => {
  const t = convexTest(schema, modules);

  await expect(
    t.mutation(api.waitlist.joinWaitlist, {
      email: "not-an-email",
      name: "Tony",
      source: "desktop",
    }),
  ).rejects.toThrow();

  const rows = await t.run((ctx) => ctx.db.query("waitlist").collect());
  expect(rows).toHaveLength(0);
});

test("a blank name is rejected and stores nothing", async () => {
  const t = convexTest(schema, modules);

  await expect(
    t.mutation(api.waitlist.joinWaitlist, {
      email: "tony@example.com",
      name: "   ",
      source: "desktop",
    }),
  ).rejects.toThrow();

  const rows = await t.run((ctx) => ctx.db.query("waitlist").collect());
  expect(rows).toHaveLength(0);
});

test("a flood is capped by the global per-minute rate limit", async () => {
  const t = convexTest(schema, modules);

  // Fill the window with distinct addresses so dedupe never masks the cap.
  for (let i = 0; i < MAX_JOINS_PER_MINUTE; i++) {
    await t.mutation(api.waitlist.joinWaitlist, {
      email: `flood${i}@example.com`,
      name: "Flooder",
      source: "desktop",
    });
  }

  await expect(
    t.mutation(api.waitlist.joinWaitlist, {
      email: "one-too-many@example.com",
      name: "Flooder",
      source: "desktop",
    }),
  ).rejects.toThrow();
});

/// <reference types="vite/client" />
import { afterEach, describe, expect, test, vi } from "vitest";
import { renderConfirmation, sendWaitlistConfirmation } from "./emailClient";

describe("renderConfirmation", () => {
  test("greets the person by name in every part", () => {
    const { subject, html, text } = renderConfirmation("Ada");
    expect(subject).toBe("You're on the Euno waitlist");
    expect(html).toContain("Hi Ada, you're on the list.");
    expect(text).toContain("Hi Ada,");
  });

  test("escapes HTML in the name so a crafted name cannot inject markup", () => {
    const { html } = renderConfirmation('<script>alert("x")</script>');
    // The raw tag must never reach the HTML body...
    expect(html).not.toContain("<script>");
    // ...it lands as escaped entities instead.
    expect(html).toContain("&lt;script&gt;");
    expect(html).toContain("&quot;");
  });

  test("escapes an ampersand so the name renders as typed", () => {
    const { html } = renderConfirmation("Tom & Jerry");
    expect(html).toContain("Tom &amp; Jerry");
    expect(html).not.toContain("Tom & Jerry");
  });

  test("leaves the plain-text part unescaped", () => {
    // Text has no markup to break out of, so entities would be noise there.
    const { text } = renderConfirmation("Tom & Jerry");
    expect(text).toContain("Hi Tom & Jerry,");
  });
});

describe("sendWaitlistConfirmation", () => {
  const original = {
    key: process.env.RESEND_API_KEY,
    from: process.env.WAITLIST_FROM_EMAIL,
  };

  afterEach(() => {
    vi.unstubAllGlobals();
    if (original.key === undefined) delete process.env.RESEND_API_KEY;
    else process.env.RESEND_API_KEY = original.key;
    if (original.from === undefined) delete process.env.WAITLIST_FROM_EMAIL;
    else process.env.WAITLIST_FROM_EMAIL = original.from;
  });

  test("skips (never sends, never throws) when credentials are unset", async () => {
    delete process.env.RESEND_API_KEY;
    delete process.env.WAITLIST_FROM_EMAIL;
    const fetchSpy = vi.fn();
    vi.stubGlobal("fetch", fetchSpy);

    const result = await sendWaitlistConfirmation({
      to: "a@b.com",
      name: "Ada",
    });

    expect(result.status).toBe("skipped");
    expect(fetchSpy).not.toHaveBeenCalled();
  });

  test("posts to Resend and reports sent once both credentials are set", async () => {
    process.env.RESEND_API_KEY = "re_test_key";
    process.env.WAITLIST_FROM_EMAIL = "Euno <hello@euno.app>";
    const fetchSpy = vi.fn(async () => Response.json({ id: "email_123" }));
    vi.stubGlobal("fetch", fetchSpy);

    const result = await sendWaitlistConfirmation({
      to: "a@b.com",
      name: "Ada",
    });

    expect(result).toEqual({ status: "sent", id: "email_123" });
    expect(fetchSpy).toHaveBeenCalledOnce();
    const [url, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
    expect(url).toBe("https://api.resend.com/emails");
    const body = JSON.parse(init.body as string);
    expect(body.from).toBe("Euno <hello@euno.app>");
    expect(body.to).toBe("a@b.com");
    expect(body.subject).toBe("You're on the Euno waitlist");
  });

  test("reports failed (not thrown) when Resend rejects the request", async () => {
    process.env.RESEND_API_KEY = "re_test_key";
    process.env.WAITLIST_FROM_EMAIL = "hello@euno.app";
    vi.stubGlobal(
      "fetch",
      async () => new Response("domain not verified", { status: 403 }),
    );

    const result = await sendWaitlistConfirmation({
      to: "a@b.com",
      name: "Ada",
    });

    expect(result.status).toBe("failed");
  });
});

